#include <string.h>

typedef unsigned long u_long;

class stringx
{
protected:
  char *chars;
  void *my_buf;

public:
  inline const char *c_str() const
  {
    return chars;
  }
};

class nglFixedString
{
public:
  typedef u_long fint;
  enum { FINT_SIZE = 8 };
  enum { STR_SIZE = 32 };
  enum { NUM_FINTS = STR_SIZE / FINT_SIZE };

  fint *value() { return reinterpret_cast<fint *>(str); }

  nglFixedString(const char *s)
  {
    for (int i = 0; i < NUM_FINTS; ++i)
      value()[i] = 0;

    strncpy(str, s, STR_SIZE - 1);
    strlwr(str);
  }

private:
  char str[STR_SIZE];
} __attribute__((aligned(8)));

struct nglTexture;
nglTexture *nglLoadTexture(const nglFixedString &FileName);

enum { TRICK_NONE = 0 };

typedef struct SurferDataStruct {
  int start_stand;
  int start_turn;
  int start_carve;
  int start_anims;
  int end_anims;
  int trickBook[70];
  int learnedtrickBook[16];
  char name[32];
  char name_ps[32];
  char stashfile[16];
  char firstname[32];
  char lastname[32];
  char fullname[32];
  char abbr[4];
  int goofy;
  int load_in_fe;
  int bio_length;
  int has_movie;
  int attr_spin;
  int attr_speed;
  int attr_balance;
  int attr_air;
  char board_ent_name[20];
  char p_board_name[20];
  int selectable;
  int competitor;
  int initially_unlocked;
  char surfer_nick[20];
  int sort_order;
} SurferData;

extern SurferData SurferDataArray[];
extern const int TRICKBOOK_SIZE;

class game
{
  char padding0[188];
  int active_player;
  char padding1[408];
  int surferIdx[2];

public:
  int get_active_player(void) { return active_player; }
  int GetSurferIdx(int hero_num) const { return surferIdx[hero_num]; }
};

extern game *g_game_ptr;

class UnlockingManager
{
public:
  bool isSurferTrickUnlocked(int trick, bool ignore_cur_level = false) const;
};

extern UnlockingManager unlockManager;

class IGOIconManager
{
public:
  class IconResource
  {
  public:
    nglTexture *texture;
    int trickIdx;
    unsigned int bitmask;
    unsigned char timesDisplayed;
    unsigned char iconType;
    bool avail;

    void Load(int type, int idx, int num, const stringx &texFilename);
  };
};

void IGOIconManager::IconResource::Load(int type, int idx, int num, const stringx & texFilename)
{
  iconType  = (unsigned char)type;
	trickIdx  = idx;
	texture   = nglLoadTexture(texFilename.c_str());

  if(idx <= TRICK_NONE)
  {
    bitmask   = 0xFFFFFFFF;
    avail     = true;
  }
  else
  {
	int i;
    bitmask   = (0x01 << num);
	int current_surfer = g_game_ptr->GetSurferIdx(g_game_ptr->get_active_player());

	// Check through all the tricks in this surfer's trickbook.  If the trick isn't there, avail = false
	bool trick_exists = false;
	for(i = 0; i < TRICKBOOK_SIZE; i++)
	{
		if(SurferDataArray[current_surfer].trickBook[i] == idx)
		{
			trick_exists = true;
			break;
		}
	}
    avail     = trick_exists && unlockManager.isSurferTrickUnlocked(idx);
  }
}
